#include "stdafx.h"#include "..\MnemoWnd.h"#include "Queue.h"#include "..\Lang.h"//// Обработка кнопок//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  //(по HS.PV м.б. 4 значения разных текста и цветов)  //если PV>4 или <0 то ничего не отображается  char szName[64];//используется как Txt0  char szGoto[64];  char szWnd [64];  char szParm[64];  char szTxt[4][64];  int nSpecHS;//1- Отображение 2- Отображение и Управление,   //0 - просто вывод кнопки с цветами по умолчанию или cTxt0 и cBkg0  int  nSet;//значение, присваемое SP HS  COLORREF colorTxt[4];  COLORREF colorBkg[4];  bool bWithoutEdge;  int nValue;  int nTeg;  bool bPump;  bool bSensor;  UINT uFormat;  bool m_bRight;  bool bReserv;  } Queue_WaterRect;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~int PressWaterRect(DefinePress)  {  Queue_WaterRect* p = (Queue_WaterRect*)s;  if ( nCode == 0 )    return 0;  else  if ( nCode == 1 )    return 0;  else  if ( nCode == 3 )    return 0;  else  if ( nCode == 2 )    {    if ( p->nRegulator != -2 )      return 0;    bool bPtInRect = ::PtInRect( &p->mRect, point ) == TRUE;    if ( !bPtInRect )      return 0;    }  //  if ( *p->szWnd != '\0' )    {    if ( lstrcmpi( p->szName, "ПОМОЩЬ" ) == 0 )      OpenMnemoWnd( q.hWnd, p->szWnd, false );    else      OpenMnemoWnd( q.hWnd, p->szWnd );    }  else  if ( *p->szGoto != '\0' )    {    static char szGoto[256];    lstrcpy( szGoto, p->szGoto );    ::PostMsg( q.hWnd, QUEUE_GOTO, (LPARAM)szGoto );    }  else  if ( lstrcmpi( p->szName, "EXIT" ) == 0 )    {    ::DestroyWindow( q.hWnd );    //::PostMessage( q.hWnd, WM_DESTROY, 0, 0 );    }  else  if ( p->nSpecHS==2)    {		CShHS* sh = (CShHS*)PipeSh;		if ( IsTypeOk )		  {		  SSendToModel send;		  lstrcpy( send.szValue, p->szParm );// Имя переменной		  bool Old = sh->mOn; //##??		  bool New = p->nSet;		  send.Set( enumValueBol, &Old, &New );		  q.m_pPipe->SendData( p->nNumber, send );		  }    }  //  return 0;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintWaterRect(DefinePaint)  {  QueueP(Queue_WaterRect);  //  RECT rc = p->mRect;  bool bSimpleButton=false;  const int dBadValue=-1021;  int nValue=dBadValue;  if (p->nTeg>=0)	nValue = ::TegValueI( p->nTeg, "value", dBadValue );  if (p->nValue!=-1)	nValue=p->nValue;  int nNumber=0;  if (p->nSpecHS!=0)  {	    if(p->bPump)		{			CShPump* sh = (CShPump*)PipeSh;			if ( IsTypeOk )			{				nNumber=0;//основной или авто				if (p->bReserv)				{					int nValue=(sh->Use_Flags%100)/10;					if (nValue!=0)						nNumber=1;//резервный				}				else				{					int nValue=sh->Use_Flags%10;					if (nValue!=0)						nNumber=1;//местный				}			}		}		else		{			if(p->bSensor)			{				CShSensor* sh = (CShSensor*)PipeSh;				if ( IsTypeOk )				{					  double dValue=sh->ShowValue;					  nNumber=0;					  double dHH = TegValueD( p->nTeg, "HH", dBadValue );					  double dH = TegValueD( p->nTeg, "H", dBadValue );					  double dLL = TegValueD( p->nTeg, "LL", dBadValue );					  double dL = TegValueD( p->nTeg, "L", dBadValue );					  if (dL!=dBadValue)						  if (dValue<=dL)							  nNumber=0;					  if (dLL!=dBadValue)				          if (dValue<=dLL)							  nNumber=0;					  if (dH!=dBadValue)						  if (dValue>=dH)							  nNumber=1;					  if (dHH!=dBadValue)				          if (dValue>=dHH)							  nNumber=1;				}			}			else			{						CShHS* sh = (CShHS*)PipeSh;						if ( IsTypeOk )						{//##??							if ((sh->PV<4)&&(sh->PV>=0))							{              if ( sh->mOn )								nNumber = 1;              else								nNumber = 0;							}						}						else							bSimpleButton=true;			}		}    }  else	  nNumber=0;  if (nValue!=dBadValue)		nNumber=nValue;	CMyBrush brush( hDC, p->colorBkg[nNumber] );	brush.Rect( rc );	COLORREF clrEdge=0;	if (p->bWithoutEdge)		clrEdge=p->colorBkg[nNumber];	CMyPen pen( hDC, clrEdge );	pen.Rect( rc );	COLORREF old = ::SetTextColor( hDC, p->colorTxt[nNumber] );	::DrawText( hDC, p->szTxt[nNumber], lstrlen(p->szTxt[nNumber]), &rc, p->uFormat );	::SetTextColor( hDC, old );  //  if ( ::GetMnemoStyle() & MNEMO_EDIT )  {  		CShHS* sh = (CShHS*)PipeSh;		if ( !IsTypeOk )		{			CMyBrush brush( hDC, 0x80ff );			brush.Rect( rc );			int nNumber=0;			if(p->nValue!=-1)				nNumber=p->nValue;			COLORREF clrEdge=0;			if (p->bWithoutEdge)				clrEdge=p->colorBkg[nNumber];			CMyPen pen( hDC, clrEdge );			pen.Rect( rc );			COLORREF old = ::SetTextColor( hDC, p->colorTxt[nNumber]);			::DrawText( hDC, p->szTxt[nNumber], lstrlen(p->szTxt[nNumber]), &rc, p->uFormat );			::SetTextColor( hDC, old );		}  }  //  return 0;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddWaterRect(DefineTegs)  {  //  AddQueueEx(Queue_WaterRect);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_BUTTON;  // Определение функции вывода  p->paint = &PaintWaterRect;  p->press = &PressWaterRect;  //  int nMultik = Multiline( p->szName, teg[0].value, sizeof(p->szName) );  p->uFormat = (nMultik) ?DT_CENTER|DT_WORDBREAK : DT_SINGLELINE|DT_VCENTER|DT_CENTER;  //  p->nSpecHS= 0;  p->nRegulator = -2;  p->nSet=0;  p->colorBkg[0]=0;  p->bWithoutEdge=false;  p->nTeg=-1;  char szHsName[64]="";  char szPumpName[64]="";  char szSensorName[64]="";  p->bPump=false;  p->bSensor=false;  p->nValue=-1;  p->m_bRight=false;  p->bReserv=false;  //  lstrcpy( p->szParm, "SP" );  //  STegObj obj[] =    {    { 'R', "rect"   , &p->mRect  },    { 'E', "rc"     , &p->mRect  },    { 'A', "cTxt0" , &p->colorTxt[0] },	{ 'A', "cTxt1" , &p->colorTxt[1] },	{ 'A', "cTxt2" , &p->colorTxt[2] },	{ 'A', "cTxt3" , &p->colorTxt[3] },	{ 'A', "cBkg0" , &p->colorBkg[0] },	{ 'A', "cBkg1" , &p->colorBkg[1] },	{ 'A', "cBkg2" , &p->colorBkg[2] },	{ 'A', "cBkg3" , &p->colorBkg[3] },    { 'S', "goto"   , p->szGoto, 63 },    { 'S', "window" , p->szWnd , 63 },    { 'S', "param"  , p->szParm, 63 },	{ 'S', "txt1"  , p->szTxt[1], 63 },	{ 'S', "txt2"  , p->szTxt[2], 63 },	{ 'S', "txt3"  , p->szTxt[3], 63 },	{ 'S', "hsName", szHsName, 63 },	{ 'S', "pumpName", szPumpName, 63 },	{ 'S', "sensorName", szSensorName, 63 },    { 'I', "specHS" , &p->nSpecHS },    { 'I', "setHS"  , &p->nSet },	{ 'I', "text", &p->nValue},	{ 'B', "withoutEdge", &p->bWithoutEdge},	{ 'B', "right"  , &p->m_bRight },	{ 'B', "reserv"  , &p->bReserv},    EXT_QUEUE  // Дополнительная информация    //    };  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  if (*szHsName)  {	p->nNumber=def.AddKind( id_HS    , szHsName );	p->nTeg = ::FindTagEx( szHsName, id_HS );  }  if (*szPumpName)  {	p->nNumber=def.AddKind( id_Pump   , szPumpName );	p->nTeg = ::FindTagEx( szPumpName, id_Pump );	p->bPump=true;  }  if (*szSensorName)  {	p->nNumber=def.AddKind( id_Sensor   , szSensorName );	p->nTeg = ::FindTagEx( szSensorName, id_Sensor );	p->bSensor=true;  }  lstrcpy(p->szTxt[0],p->szName);     if(p->m_bRight)		p->uFormat=DT_RIGHT|DT_VCENTER|DT_WORDBREAK;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~